{"command":"python3 -c "import json
with open('extracted_languages.json') as f: data = json.load(f)
with open('languages.txt') as f: 
    lines = f.read().splitlines()
lang_exts = {}
import re
for line in lines:
    m = re.match(r'^(.*?)\s+\((.*?)\)$', line.strip())
    if m: lang_exts[m.group(1).strip()] = [e.strip() for e in m.group(2).split(',')]

clean = {}
for k, v in data.items():
    if not lang_exts.get(k): continue
    if not v['line_comments'] and not v['multi_comments'] and not v['complexity']:
        # if it's a known plain text, maybe keep?
        pass
    v['exts'] = lang_exts[k]
    clean[k] = v

with open('clean_langs.json', 'w') as f: json.dump(clean, f)
print(len(clean))
""}

